'use strict';
const originalIcon='./assets/icon-rounded-512.png';
let planSnapshot,recordContext,progressInfo,bindScreen;

'use strict';
const $=s=>document.querySelector(s), esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let aboutBack='today';
let recipeIndex=0;
const icon=n=>`<svg class="icon" aria-hidden="true"><use href="#i-${n}"/></svg>`;
const header=(k,t,p='')=>`<div class="screen-header"><p class="eyebrow">${k}</p><h1 tabindex="-1">${t}</h1>${p?`<p>${p}</p>`:''}</div>`;
const back=(view='today',label='Назад')=>`<button class="textbutton back" data-go="${view}">${icon('back')}${label}</button>`;
const notice=(text,type='')=>`<div class="notice ${type}">${text}</div>`;
const steps=['Крекер и хлеб','Печенье','Маффины: первая группа','Маффины: вторая группа','Фрикадельки и оладьи','Яйцо вкрутую','Яичная болтунья'];
let state,view='today',filter='all',dateFilter='',selectedStep=0,editId=null,toastTimer;
function message(t){$('#toast').textContent=t;$('#toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').hidden=true,4500);}
const screens={};
screens.welcome=()=>header('Давайте познакомимся','У каждого ребёнка<br>свой темп.','ЕмЯйцо помогает записывать выполнение назначенного врачом плана и наблюдения семьи.')+`<div class="recipe-visual"><span class="welcome-logo" data-original-icon></span></div><div class="stack">${notice('<strong>Сначала — решение врача.</strong><br>Дневник не определяет, подходит ли ребёнку домашняя лестница, и не назначает стартовую форму или порцию.','warn')}<div class="card"><h3>Три понятных шага</h3><div class="mini-row"><span class="circle">1</span><div><strong>Перенесите назначение</strong><p>Форму яйца, рецепт, количество и порядок наблюдения.</p></div></div><div class="mini-row"><span class="circle">2</span><div><strong>Ведите дневник</strong><p>Приёмы, пропуски и симптомы, в том числе отсроченные.</p></div></div><div class="mini-row"><span class="circle">3</span><div><strong>Обсудите историю</strong><p>Покажите врачу записи и вопросы на приёме.</p></div></div></div><button class="primary wide" data-go="plan">Перенести план врача</button><button class="wide" data-go="diary">Посмотреть пустой дневник</button></div>`;
const dailyLabels={well:'Ребёнок здоров; кожа, живот и стул без обострения',asthma:'Нет признаков обострения астмы / бронхообструкции',changes:'Нет новых изменений, требующих обсуждения с врачом',prepared:'Продукт по выбранному рецепту, порция, время наблюдения и план помощи подготовлены'};
function dailyText(){if(state.paused)return 'Маршрут на паузе после симптомов. Заполненный чек-лист не отменяет паузу. Дальнейшие действия согласуйте с врачом.';if(state.restricted)return 'Для ребёнка выбран индивидуальный маршрут со специалистом.';return Object.keys(dailyLabels).every(k=>state.daily[k])?'Чек-лист заполнен. Дальнейшие действия — по плану врача.':'Если пункт не выполнен или есть сомнение, отложите приём / повышение и уточните действия.';}
function calendarState(date){const rows=state.records.filter(r=>r.date===date);if(rows.some(r=>['symptom','danger'].includes(r.symptom)))return 'symptom';if(rows.some(r=>r.symptom==='pending'||r.kind==='intake'&&r.symptom==='none'&&!entryWindowsClosed(r)))return 'pending';if(rows.some(r=>r.kind==='intake'&&r.symptom==='none'&&entryWindowsClosed(r)))return 'ok';if(rows.some(r=>r.kind==='skip'))return 'skip';if(rows.length)return 'pending';return 'empty';}
const calendarNames={ok:'наблюдение завершено без симптомов',symptom:'симптомы',pending:'наблюдение',skip:'пропуск',empty:'нет записи'};
const calendarMarks={ok:'✓',symptom:'!',pending:'◌',skip:'—',empty:'·'};
function dayDescription(){const rows=state.records.filter(r=>r.date===state.selectedDay);return dateLabel(state.selectedDay)+': '+(rows.length?rows.map(r=>(r.kind==='skip'?'пропуск':r.kind==='observation'?'наблюдение':r.amount+(r.unit?' '+r.unit:''))+' · '+statusLabel(r)).join('; '):'нет записи');}
screens.today=()=>{if(!state.assigned)return screens.welcome();return `<p class="em-eyebrow">${new Date().toLocaleDateString('ru-RU',{weekday:'long',day:'numeric',month:'long'})}</p><h1 class="family-title" tabindex="-1">В своём темпе.<br>По плану врача.</h1><button type="button" class="em-link" data-go="guide">Правила перед началом</button>
${state.paused?`<div class="em-notice em-alert" role="status"><strong>Пауза после симптомов.</strong><p>Прекратите текущую пробу. Следуйте индивидуальному плану помощи. Дальнейшее употребление и изменения обсудите с врачом.</p><button type="button" class="em-link" data-go="help">При реакции</button></div>`:state.restricted?`<div class="em-notice">Индивидуальное ведение со специалистом. Домашняя лестница не предлагается; записи наблюдений доступны.</div>`:''}
<div class="em-card em-current" id="current-step-card"><span class="em-pill">Ступень 1${state.paused?' · на паузе':state.restricted?' · не активна':''}</span><h3 style="margin-top:15px">Печёное яйцо<br>в выпечке</h3><p class="em-note">Яичная лестница · маршрут по плану врача</p><div class="em-dose">Цель: ${esc(state.plan.goal)}</div><p class="em-note">Назначенное количество: <strong>${esc(state.plan.amount)}</strong>.</p><p class="em-note"><strong>Условия завершения:</strong> согласованная порция и частота, назначенный период наблюдения, отсутствие отмеченных симптомов. Итог ступени и дальнейшие действия обсуждаются с врачом.</p><p class="em-small">Период: ${esc(state.plan.period)}. Число записей само по себе не засчитывает ступень.</p><button type="button" class="em-primary em-wide" data-action="new-entry">Записать приём или пропуск</button><button type="button" class="em-link" data-go="recipe">Продукт и приготовление</button></div>
<div class="em-card" id="daily-card"><h3>Перед сегодняшним приёмом</h3><div id="daily-checks">${Object.entries(dailyLabels).map(([key,label])=>`<label class="em-check"><input type="checkbox" data-daily="${key}" ${state.daily[key]?'checked':''}><span>${label}</span></label>`).join('')}</div><p id="daily-result" class="em-note" aria-live="polite">${dailyText()}</p><p class="em-small">Чек-лист не выдаёт медицинский допуск. При болезни, обострении или новых симптомах отложите пробу и уточните действия у врача. Уже произошедшие события можно записать независимо от отметок.</p></div>
<div class="em-card" id="week-card"><div class="em-row"><h3>Последние 7 дней</h3><button type="button" class="em-link" data-go="diary">Все записи</button></div><div class="em-week">${Array.from({length:7},(_,i)=>{const date=recentDate(i-6),st=calendarState(date);return `<button type="button" class="em-day" data-day="${date}" data-status="${st}" aria-pressed="${date===state.selectedDay}" aria-label="${dateLabel(date)}: ${calendarNames[st]}"><span>${new Date(date+'T12:00:00').toLocaleDateString('ru-RU',{weekday:'short'})}</span>${Number(date.slice(-2))}<b>${calendarMarks[st]}</b></button>`;}).join('')}</div><p class="em-legend">✓ наблюдение завершено без симптомов · ! симптомы · ◌ наблюдение · — пропуск · · нет записи</p><p id="day-detail" class="em-note" aria-live="polite">${esc(dayDescription())}</p></div>
<button type="button" class="em-wide" data-go="progress">Можно ли обсуждать следующую ступень?</button>`;};
const statusLabel=r=>({none:'Без симптомов по записи',pending:'Наблюдение продолжается',symptom:'Отмечены симптомы',danger:'Опасные признаки',skip:'Приёма не было'}[r.symptom]||'Запись');
const dateLabel=d=>new Date(d+'T12:00:00').toLocaleDateString('ru-RU',{day:'numeric',month:'long'});
function recordsList(records,edit=true){return records.map(r=>`<article class="entry-card ${r.symptom==='pending'?'pending':['symptom','danger'].includes(r.symptom)?'symptom':''}"><div class="row"><span class="small">${dateLabel(r.date)} · ${esc(r.time)}</span><span class="pill ${['symptom','danger'].includes(r.symptom)?'red':r.symptom==='none'?'green':'gold'}">${r.kind==='skip'?'Пропуск':r.kind==='observation'?'Наблюдение':esc(r.phase)}</span></div><h3>${r.kind==='skip'?'Приёма не было':r.kind==='observation'?'Наблюдение за самочувствием':esc(r.amount+(r.unit?' '+r.unit:''))}</h3><p>${statusLabel(r)}</p>${recordContext(r)}${r.onset?`<p>Время появления: ${esc(r.onset)}</p>`:''}${r.note?`<p>${esc(r.note)}</p>`:''}${edit?`<button class="textbutton" data-edit="${r.id}">Уточнить запись →</button>`:''}</article>`).join('');}
screens.diary=()=>{const filtered=state.records.filter(r=>(!dateFilter||r.date===dateFilter)&&(filter==='all'||filter==='symptoms'&&['symptom','danger'].includes(r.symptom)||filter==='pending'&&r.symptom==='pending'||filter==='skip'&&r.kind==='skip')).slice().sort((a,b)=>(b.date+b.time).localeCompare(a.date+a.time));return header('ЗАПИСИ СЕМЬИ','Ничего не нужно<br>держать в памяти.','В том числе пропуски и симптомы, появившиеся позже.')+`<div class="grid2"><button class="primary" data-action="new-entry">+ Запись</button><button data-go="report">Отчёт для врача</button></div><div class="chips" aria-label="Фильтр записей">${[['all','Все'],['symptoms','Симптомы'],['pending','Наблюдение']].map(([id,label])=>`<button data-filter="${id}" aria-pressed="${filter===id}">${label}</button>`).join('')}</div>${dateFilter?`<button class="textbutton" data-action="clear-date">${dateLabel(dateFilter)} · показать все даты ×</button>`:''}${filtered.length?recordsList(filtered):`<div class="empty"><div class="circle">${icon('diary')}</div><h3>Здесь пока нет записей</h3><p>Пустой день не означает, что приём был или что симптомов не было.</p></div>`}`;};
screens.guide=()=>back('more','Памятка')+header('ПЕРЕД НАЧАЛОМ ЯИЧНОЙ ЛЕСТНИЦЫ','Один маршрут.<br>В своём темпе.','ЕмЯйцо — дневник домашней яичной лестницы, которую ребёнку назначил лечащий врач.')+`<div class="em-card"><h3>Начало согласуйте с врачом</h3><p class="em-note">Аллерголог определяет, подходит ли ребёнку домашний путь, стартовую ступень, конкретную форму яйца, количество и порядок наблюдения. Приложение не выбирает путь по анкете или анализу IgE.</p><button class="em-link" data-go="plan">Открыть план врача</button></div><div class="em-card"><h3>Готовим по выбранному рецепту</h3><p class="em-note">Состав, количество яйца, выход партии, температура и время приготовления должны совпадать с назначенным рецептом. Другой продукт или размер изделия не считаются равноценной заменой.</p><button class="em-link" data-go="recipe">Продукт и приготовление</button></div><div class="em-card"><h3>Наблюдение важнее счётчика</h3><p class="em-note">Для каждой формы отдельно учитываются количество, частота, период и наблюдения. Отмечайте приёмы и пропуски, дополняйте записи поздними симптомами. Маленькие порции не складываются в полную; три записи не разрешают переход автоматически.</p><button class="em-link" data-go="progress">Что обсудить перед следующей ступенью</button></div><div class="em-card"><h3>При симптомах — пауза</h3><p class="em-note">Прекратите текущую пробу, выполняйте индивидуальный план помощи и свяжитесь с врачом.</p><p class="em-note"><strong>При любом из следующих опасных признаков вызывайте 112 / 103:</strong></p><ul class="em-red-flags">
 <li>Затруднённое или шумное дыхание, свисты или хрипы.</li>
 <li>Осиплость голоса, отёк языка или горла.</li>
 <li>Обморок, резкая бледность или выраженная внезапная вялость.</li>
 <li>Резкая сильная боль в животе.</li>
 <li>Многократная рвота с вялостью.</li>
</ul><p class="em-note">Не ждите сыпи или ответа врача в чате. <button type="button" data-go="help" class="em-link">План срочной помощи</button></p></div><label class="em-check"><input type="checkbox" id="em-read-guide" ${state.guideAcknowledged?'checked':''}><span>Понимаю: начало и изменения согласуются с врачом. Знаю, как действовать при реакции.</span></label><button type="button" id="em-guide-done" class="em-primary em-wide" data-go="today" ${state.guideAcknowledged?'':'disabled'}>Перейти к дневнику</button>`;
screens.help=()=>`<div class="em-eyebrow">План действий</div><h2>Если появилась реакция</h2><div class="em-card em-emergency"><h3>Опасные признаки</h3><ul class="em-red-flags">
 <li>Затруднённое или шумное дыхание, свисты или хрипы.</li>
 <li>Осиплость голоса, отёк языка или горла.</li>
 <li>Обморок, резкая бледность или выраженная внезапная вялость.</li>
 <li>Резкая сильная боль в животе.</li>
 <li>Многократная рвота с вялостью.</li>
</ul><p class="em-emergency-number"><a href="tel:112">112</a> / <a href="tel:103">103</a></p><p class="em-small">Экстренная помощь в России.</p><ol><li>Прекратите кормление. Не оставляйте ребёнка одного.</li><li>При подозрении на анафилаксию немедленно используйте назначенный адреналин по индивидуальному плану и вызывайте скорую. Не ждите появления сыпи или ответа врача в чате.</li><li>Уложите ребёнка, не позволяйте вставать и ходить. При затруднении дыхания допустимо положение сидя с вытянутыми ногами; при рвоте или потере сознания — на боку. Выполняйте указания диспетчера.</li></ol><p class="em-note">Антигистаминные и системные гормональные препараты (глюкокортикостероиды) не заменяют адреналин при анафилаксии. Их применение не должно задерживать введение адреналина и вызов скорой помощи. При FPIES необходим отдельный план врача.</p></div>
     <div class="em-card"><h3>Другие или отсроченные симптомы</h3><p class="em-note">Прекратите текущую пробу, действуйте по письменному плану и свяжитесь с врачом. Не увеличивайте порцию и не переходите дальше. При ухудшении вызывайте скорую.</p><button type="button" data-go="diary" class="em-wide">После оказания помощи — дополнить дневник</button></div>
     <p class="em-small">Следуйте персональному плану помощи с назначенными препаратами и дозами. Держите его доступным семье и отдельно от телефона.</p>`;
function reportText(){return ['ЕмЯйцо — ОТЧЁТ ДЛЯ ВРАЧА, НЕ МЕДИЦИНСКОЕ НАЗНАЧЕНИЕ','Пациент: '+state.name+' · дата рождения: '+(state.dob||'не указана'),'План: '+state.plan.protocol,'Цель ступени: '+state.plan.goal,'Период: '+state.plan.period,'Количество: '+state.plan.amount,'Частота: '+state.plan.frequency,'Наблюдение: '+state.plan.observe,'Пауза: '+(state.paused?'да':'нет'),'',...state.records.map(r=>`${r.date} ${r.time} | ${r.kind==='skip'?'Пропуск':r.kind==='observation'?'Наблюдение':r.amount+' '+r.unit} | ${statusLabel(r)} | ${r.onset} | ${r.note}`),'','Вопросы врачу: '+($('#report-question')?.value||'Обсудить текущую форму, порцию и дальнейший план.')+(state.question?'\nМожно ли обсуждать следующую ступень? Какие условия нужно выполнить?':''),'','Записи со слов семьи. Не подтверждают переносимость или разрешение перехода.'].join('\n');}
screens.report=()=>back('diary','К дневнику')+header('ОТЧЁТ ДЛЯ ВРАЧА','Вся история —<br>к одному приёму.','Покажите наблюдения и вопросы врачу. Отчёт не оценивает эффективность лечения.')+`<div class="card"><div class="row"><h3 style="margin:0">${esc(state.name)}</h3></div><div class="metric-row"><span>Записей</span><strong>${state.records.length}</strong></div><div class="metric-row"><span>С симптомами</span><strong>${state.records.filter(r=>['symptom','danger'].includes(r.symptom)).length}</strong></div><div class="metric-row"><span>Наблюдение не завершено</span><strong>${state.records.filter(r=>r.symptom==='pending').length}</strong></div><div class="metric-row"><span>Текущий статус</span><strong>${state.paused?'Пауза после симптомов':state.restricted?'Индивидуальное ведение':state.assigned?'План врача внесён':'План не внесён'}</strong></div></div><div class="card"><h3>План из дневника</h3><p class="small">${esc(state.plan.protocol)}</p><div class="metric-row"><span>Цель ступени</span><strong>${esc(state.plan.goal)}</strong></div><div class="metric-row"><span>Период</span><strong>${esc(state.plan.period)}</strong></div><div class="metric-row"><span>Количество</span><strong>${esc(state.plan.amount)}</strong></div><div class="metric-row"><span>Частота</span><strong>${esc(state.plan.frequency)}</strong></div><div class="metric-row"><span>Наблюдение</span><strong>${esc(state.plan.observe)}</strong></div></div><h3 class="section-title">Записи по датам</h3>${state.records.length?recordsList(state.records,false):notice('Записей пока нет.')}${state.question?`<div class="em-notice" id="transition-question"><strong>Вопрос о переходе</strong><p>Можно ли обсуждать следующую ступень? Какие условия нужно выполнить?</p></div>`:''}<label class="form-field">Вопрос врачу<textarea id="report-question" maxlength="1000" placeholder="Что хотели бы обсудить?">${esc(state.reportQuestion||'')}</textarea></label><div class="grid2 no-print"><button class="primary" data-action="print">Печать / PDF</button><button data-action="download-report">Скачать текст</button></div><p class="small" style="margin-top:14px">Отчёт содержит данные выбранного пациента. Автоматической отправки врачу нет.</p>`;
function download(name,text){const url=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function bindScreenBase(){
 if(view==='guide')$('#em-read-guide').addEventListener('change',e=>{state.guideAcknowledged=e.target.checked;persist();$('#em-guide-done').disabled=!state.guideAcknowledged;});
 if(view==='today')document.querySelectorAll('[data-daily]').forEach(input=>input.addEventListener('change',()=>{resetDaily();state.daily[input.dataset.daily]=input.checked;persist();$('#daily-result').textContent=dailyText();}));
}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||b.disabled)return;if(b.dataset.go){if(b.dataset.go==='recipe')recipeIndex=Math.max(0,recipes.findIndex(r=>r.id===state.plan.recipeId));render(b.dataset.go);return;}if(b.dataset.recipe!==undefined){recipeIndex=Number(b.dataset.recipe);render('recipe');return;}if(b.dataset.step!==undefined){selectedStep=Number(b.dataset.step);render('step');return;}if(b.dataset.filter){filter=b.dataset.filter;render('diary');return;}if(b.dataset.day){state.selectedDay=b.dataset.day;document.querySelectorAll('[data-day]').forEach(x=>x.setAttribute('aria-pressed',String(x.dataset.day===state.selectedDay)));$('#day-detail').textContent=dayDescription();return;}if(b.dataset.date){dateFilter=b.dataset.date;filter='all';render('diary');return;}if(b.dataset.edit){editId=b.dataset.edit;render('entry');return;}switch(b.dataset.action){case 'add-transition-question':state.question=true;render('progress');message('Вопрос добавлен в отчёт. Врачу ничего не отправлено.');break;case 'new-entry':editId=null;render('entry');if(state.paused){$('#kind').value='observation';$('#kind').dispatchEvent(new Event('change'));}break;case 'new-observation':editId=null;render('entry');$('#kind').value='observation';$('#kind').dispatchEvent(new Event('change'));break;case 'clear-date':dateFilter='';render('diary');break;case 'print':window.print();break;case 'download-report':download('em-yaytso-report.txt',reportText());message('Отчёт подготовлен.');break;}});
screens.about=()=>back(aboutBack,'Вернуться к дневнику')+header('О ПРИЛОЖЕНИИ','ЕмЯйцо','Дневник назначенной врачом яичной лестницы.')+
 `<div class="em-about-brand"><span class="about-icon" data-original-icon></span><div><strong>ЕмЯйцо</strong><p class="em-note">Для семьи и её врача</p></div></div><p>«ЕмЯйцо» помогает родителям вести дневник назначенной врачом яичной лестницы: отмечать продукты и порции, приёмы и пропуски, сохранять наблюдения о симптомах и готовить сводку к консультации.</p><p class="em-note">Маршрут, рецепты, порции, условия изменения ступени и действия при реакции определяет лечащий врач. Приложение не диагностирует аллергию, не назначает лечение и не заменяет индивидуальный план помощи.</p><div class="em-card"><h3>Для кого этот дневник</h3><p class="em-note">Для семей, которым врач уже назначил домашнюю яичную лестницу. Возможность домашнего пути, в том числе при IgE-аллергии, определяет специалист. Приложение не проводит самостоятельный отбор и не предназначено для домашней диагностической пробы.</p></div><div class="em-card"><h3>Данные и текущая версия</h3><p class="em-note">Версия 1.0.2. Дневники сохраняются на этом устройстве отдельно для каждого пациента. Создавайте резервные копии: удаление данных браузера удалит дневники.</p><p class="em-note">Записи не отправляются автору или врачу. В разделе «Данные и установка» доступны резервная копия всех пациентов, восстановление и инструкции для Android и iPhone.</p><button type="button" class="em-wide" data-go="settings">Данные и установка</button><p class="em-note">Приложение не проходило клиническую валидацию и не подтверждает безопасность пробы для ребёнка.</p></div><div class="em-card"><h3>Авторские права</h3><p class="em-author-copy">© 2026 Коршунов Максим Александрович. Все права защищены.</p><p class="em-author-copy">Уведомление относится к материалам приложения, права на которые принадлежат Коршунову Максиму Александровичу. Их копирование и распространение допускаются с разрешения правообладателя, кроме случаев, предусмотренных законом.</p><p class="em-author-copy">Права на сторонние материалы, включая клинические рекомендации, публикации и рецепты, принадлежат соответствующим правообладателям. Ссылки на источники не означают одобрения приложения профессиональными обществами.</p></div>`;
function applyOriginalIcon(){
 document.querySelectorAll('[data-original-icon]').forEach(slot=>{
  const img=document.createElement('img');img.src=originalIcon;
  img.alt='ЕмЯйцо — иконка автора';img.className='original-icon';
  slot.replaceChildren(img);
 });
 for(const [id,src] of [['app-favicon','./assets/icon-rounded-192.png'],['app-touch-icon','./assets/icon-rounded-180.png']]){const link=document.getElementById(id);if(link.getAttribute('href')!==src)link.setAttribute('href',src);}
}

screens.more=()=>`<p class="em-eyebrow">Всегда под рукой</p><button type="button" class="em-link hub-settings-link" data-go="settings">Данные и установка</button><h1 class="family-title" tabindex="-1">Памятка</h1><div class="hub-buttons"><button type="button" class="em-primary em-wide" data-go="guide">Перед началом</button><button type="button" class="em-wide" data-go="rules">Порции, наблюдение и переход</button><button type="button" class="em-wide" data-go="recipes">Рецепты и продукты</button></div>
<details id="who-for"><summary>Для кого этот трекер</summary><p class="em-note">Для родителей ребёнка с подтверждённой аллергией к белкам куриного яйца, которому лечащий аллерголог уже назначил домашнюю яичную лестницу.</p><p class="em-note">Домашний путь может рассматриваться при лёгких отсроченных / не-IgE реакциях и у отдельных детей с IgE-аллергией после оценки специалистом. Сам факт IgE-аллергии не даёт ни автоматического разрешения, ни автоматического исключения: решение принимает врач с учётом истории реакций и сопутствующих состояний.</p><p class="em-note">При FPIES, предыдущей анафилаксии, дыхательных или сердечно-сосудистых проявлениях, неконтролируемой астме, тяжёлой реакции на печёное яйцо или неясном диагнозе не используйте стандартную домашнюю лестницу самостоятельно. Нужны индивидуальная тактика и план помощи от специалиста.</p><p class="em-note">Уровень специфического IgE или результат кожной пробы сами по себе не определяют безопасность домашней пробы. Дневник не проводит диагностическую пищевую провокацию и не назначает иммунотерапию.</p><p class="em-small">Медицинские критерии и конкретный протокол ещё не утверждены, клиническая валидация приложения не проводилась.</p></details>
<details id="sources"><summary>Источники и международные рекомендации</summary>
<h3>Аллергия к яйцу и назначение лестницы</h3>
<p class="em-note source-note"><a href="https://onlinelibrary.wiley.com/doi/10.1111/cea.14009" target="_blank" rel="noopener noreferrer">BSACI, 2021 · руководство по ведению аллергии к яйцу</a> — профильное руководство по диагностике и ведению; выбор домашнего введения или медицинского наблюдения относится к решению специалиста.</p>
<p class="em-note source-note"><a href="https://pubmed.ncbi.nlm.nih.gov/35692059/" target="_blank" rel="noopener noreferrer">Chua и соавт., 2022 · отбор пациентов для пищевых лестниц</a> — обсуждение возраста, астмы, анафилаксии и возможности семьи соблюдать план. Это не автоматический тест допуска для пациента.</p>
<h3>Практические материалы и рецепты</h3>
<p class="em-note source-note"><a href="https://allergynorthwest.nhs.uk/resources/allergy-leaflets/gradual-introduction-egg-egg-ladder/" target="_blank" rel="noopener noreferrer">North West Paediatric Allergy Network NHS · яичная лестница</a> — региональная памятка по постепенному введению яйца. Использование конкретной схемы согласуется с врачом.</p>
<p class="em-note source-note"><a href="https://www.uhb.nhs.uk/media/cwlgr203/pi-nut-die-reintroduction-egg-child.pdf" target="_blank" rel="noopener noreferrer">University Hospitals Birmingham NHS · повторное введение яйца</a> — материал с примерами продуктов и рецептов. Состав, приготовление, выход партии и порции требуют сверки с выбранной версией документа.</p>
<p class="em-note source-note"><a href="https://www.yorkhospitals.nhs.uk/seecmsfile/?id=7363" target="_blank" rel="noopener noreferrer">York and Scarborough NHS · рекомендации по введению яйца</a> — ещё один локальный вариант. Его шкалу количества и сроки не следует автоматически смешивать со схемой другой службы.</p>
<h3>Питание и ведение пищевой аллергии</h3>
<p class="em-note source-note"><a href="https://pubmed.ncbi.nlm.nih.gov/39473345/" target="_blank" rel="noopener noreferrer">EAACI, 2025 · ведение IgE-опосредованной пищевой аллергии</a> — общие принципы питания, обучения семьи и индивидуального плана помощи. Это не единая универсальная яичная лестница.</p>
<h3>Экстренная помощь</h3>
<p class="em-note source-note"><a href="https://www.resus.org.uk/library/additional-guidance/guidance-anaphylaxis/emergency-treatment-anaphylactic-reactions" target="_blank" rel="noopener noreferrer">Resuscitation Council UK, 2021 · экстренная помощь при анафилаксии</a> — источник по распознаванию и лечению анафилаксии. В семье используют персональный план помощи и местные экстренные номера.</p>
<h3>Исследования стандартизации</h3>
<p class="em-note source-note"><a href="https://pubmed.ncbi.nlm.nih.gov/41556404/" target="_blank" rel="noopener noreferrer">Hicks и соавт., 2026 · стандартизированная яичная лестница</a> — исследовательская работа, приведённая в авторском обзоре. Не используется в приложении как готовый утверждённый домашний протокол.</p>
<p class="em-small">Эти документы решают разные задачи. Ссылки не устанавливают универсальные порции, сроки или автоматическое правило перехода. Конкретный маршрут для «ЕмЯйцо» предстоит согласовать с автором-врачом.</p><p class="em-small">Список подготовлен по предоставленному авторскому обзору; полные тексты и актуальные версии перед публикацией приложения требуют сверки. Права на источники принадлежат их правообладателям. Профессиональные общества не подтверждали клиническую валидацию приложения.</p></details>`;

screens.rules=()=>back('more','Памятка')+header('ЗАПИСИ И НАБЛЮДЕНИЕ','Как ведём дневник','Форма яйца, количество готового продукта и период наблюдения учитываются отдельно.')+
`<details open><summary>Перед приёмом</summary><p class="em-note">Следуйте уже назначенному плану. При болезни, новых симптомах, обострении кожи или астмы, изменении лекарств и других обстоятельствах уточните действия у врача. Подготовьте согласованный продукт, количество, время наблюдения и план помощи.</p><p class="em-note">Не отменяйте лекарства самостоятельно ради пробы. Чек-лист помогает ничего не забыть, но не подтверждает безопасность введения.</p><button type="button" class="em-link" data-go="today">Открыть сегодняшний чек-лист</button></details>
<details open><summary>Что считается полной порцией</summary><p class="em-note">Полной считается целевая порция конкретного продукта из назначения врача при соблюдении выбранного рецепта, состава, выхода партии и приготовления. Для другого рецепта или размера изделия это количество нельзя автоматически переносить.</p><div class="em-notice"><strong>В плане врача:</strong><p class="em-note">Цель: ${esc(state.plan.goal)}.<br>Количество: ${esc(state.plan.amount)}.</p></div><p class="em-note">Вносите фактически съеденное количество и его единицу. Доля готового изделия — не то же самое, что доля яйца или масса аллергенного белка. Маленькие порции разных приёмов не складываются в одну полную.</p><button type="button" class="em-link" data-go="plan">Сверить назначение</button></details>
<details><summary>Наблюдение и обсуждение следующей ступени</summary><p class="em-note">Частоту, наращивание количества, длительность наблюдения и период перед обсуждением следующей формы задаёт врач.</p><p class="em-note">Пока наблюдение не завершено, оставляйте соответствующую отметку. После окончания дополните запись; при поздних симптомах уточните её снова. Наращивание, другой рецепт, незавершённое наблюдение и несколько записей за одну дату не увеличивают число отдельных полных приёмов.</p><button type="button" class="em-link" data-go="progress">Можно ли обсуждать следующую ступень?</button></details>
<details><summary>Симптомы и пропуски</summary><p class="em-note">Запишите, что произошло и когда: симптомы могут появиться позже. При реакции прекратите текущую пробу, действуйте по персональному плану помощи и свяжитесь с врачом. Не увеличивайте порцию и не переходите дальше самостоятельно.</p><p class="em-note">Пропуск отмечается отдельно и не считается приёмом без симптомов. Не удваивайте количество после пропуска. Возобновление, возвращение к продукту и дальнейшую частоту согласуйте с врачом.</p><button type="button" class="em-link" data-go="help">Если появилась реакция</button></details>
<details><summary>После завершения назначенного этапа</summary><p class="em-note">История приёмов не доказывает исчезновение аллергии. Следующую форму и дальнейший рацион определяет врач. Сырое или недостаточно приготовленное яйцо не является обязательной целью дневника.</p><button type="button" class="em-link" data-go="report">Подготовить сведения для врача</button></details>`;

const phenotypeNames={ige:'IgE-опосредованная аллергия',delayed:'Отсроченная / не-IgE аллергия',fpies:'FPIES',eoe:'EoE / другие EGID',unclear:'Диагноз или фенотип уточняется'};
const evidence=()=>`<div class="em-notice evidence"><strong>Hicks, 2026: аналитическая стандартизация.</strong><p class="em-note">Клиническая валидация этой семиступенчатой лестницы не проводилась. Лабораторный анализ рецептов не подтверждает безопасность, эффективность или подходящую порцию для конкретного ребёнка.</p><p class="em-small">Здесь — проектная русскоязычная адаптация предоставленных материалов. Точность соответствия Appendix S2 и спорные места рецептур ещё требуют сверки.</p></div>`;
const metrics=rows=>rows.map(([k,v])=>`<div class="metric-row"><span>${k}</span><strong>${esc(v)}</strong></div>`).join('');
function inputField(label,name,value='',type='text',required=false,extra=''){return `<label class="form-field">${label}<input name="${name}" type="${type}" value="${esc(value)}" ${required?'required':''} ${type==='text'?'maxlength="240"':''} ${extra}></label>`;}
const selectField=(label,name,options,value)=>`<label class="form-field">${label}<select name="${name}" id="plan-${name}">${options.map(([id,text])=>`<option value="${esc(id)}" ${id===value?'selected':''}>${esc(text)}</option>`).join('')}</select></label>`;
const clinicalRecipe=()=>recipes.find(r=>r.id===state.plan.recipeId)||recipes.find(r=>r.step===state.plan.stage)||recipes[0];
function routeStatus(p){
 if(p.phenotype==='eoe')return 'При EoE/EGID обычная лестница по дневнику симптомов не применяется. Нужен отдельный план контроля заболевания; отсутствие жалоб не заменяет обследование.';
 if(p.phenotype==='unclear')return 'Сначала уточняется диагноз. Лестница не заменяет диагностическую пищевую пробу.';
 if(p.phenotype==='fpies')return p.fpiesSeverity==='severe'?'Тяжёлый FPIES: общий домашний маршрут не применяется. Дальнейшее введение — в специализированном ведении.':'FPIES: отдельный маршрут специалиста и отдельный план помощи. Общие критерии перехода в приложении не применяются.';
 if(p.asthma==='uncontrolled')return 'Домашнее введение отложено до контроля астмы и повторной оценки специалистом.';
 if(p.asthma==='unknown')return 'Статус астмы необходимо уточнить у врача; домашний маршрут пока не подтверждён.';
 if(p.anaphylaxis||p.setting==='specialist'||p.phenotype==='ige'&&Number(p.age)>=6)return 'Специализированное ведение. Место введения и условия определяет специалист; общий домашний маршрут здесь не активируется.';
 if(!p.clinicianConfirmed)return 'Назначение домашнего маршрута врачом пока не подтверждено в записи.';
 return p.phenotype==='delayed'?'Отсроченный фенотип: окна наблюдения и критерии изменений задаёт врач. Универсального срока 24/48/72 часа для всех детей нет.':'IgE-фенотип: домашний путь только после отбора специалистом. Заполненные поля не являются самостоятельным допуском.';
}
function homeRoute(p){return EggModel.canHome(p);}
function recipeButton(r){const i=recipes.indexOf(r);return `<button type="button" class="em-wide recipe-button" data-recipe="${i}"><strong>${esc(r.name)}</strong><small>${esc(r.portion)} · ${r.estimated} мг Egg Content, расчёт в сборнике</small><small>${r.blocked?'Требует уточнения рецептуры':r.id===state.plan.recipeId&&state.assigned?'Выбран в плане врача':'Справочная карточка · не назначение'}</small></button>`;}
screens.ladder=()=>header('СЕМЬ СТУПЕНЕЙ','Яичная лестница','Рецептурная основа — Hicks, 2026. Маршрут, старт и конечную цель выбирает врач.')+evidence()+`<div class="em-ladder">${steps.map((s,i)=>`<button class="em-step" data-step="${i}"><span class="em-step-num">${i+1}</span><span><strong>${s}</strong><small>${state.assigned&&clinicalRecipe().step===i+1?'Текущая ступень плана врача':recipes.filter(r=>r.step===i+1).length+' рецепта / формы'}${i===6?' · соответствие оригиналу уточняется':''}</small></span><span aria-hidden="true">›</span></button>`).join('')}</div><p class="em-note">Номер не означает разрешение пробы. Рецепты одной ступени не взаимозаменяемы по массе продукта или лабораторному показателю. Сырое яйцо не добавлено как обязательная цель.</p><button class="em-wide" data-go="plan">План врача</button>`;
screens.step=()=>back('ladder','Семь ступеней')+header('СТУПЕНЬ '+(selectedStep+1),steps[selectedStep],'Конкретный рецепт и порцию выбирают в назначении врача.')+notice('Просмотр карточки не меняет ступень и не разрешает введение.','warn')+`<div class="recipe-list">${recipes.filter(r=>r.step===selectedStep+1).map(recipeButton).join('')}</div>`+evidence();
screens.plan=()=>{const p=state.plan;return header('НАЗНАЧЕНИЕ СПЕЦИАЛИСТА','План — от врача.<br>История — у вас.','Перенесите готовое назначение. Данные сохраняются только на этом устройстве.')+evidence()+`${state.paused?notice('Пауза после симптомов сохраняется. Изменение плана не означает возобновление проб.','danger'):''}<form id="plan-form"><fieldset class="clinical-fields"><legend>1. Клинический маршрут</legend>${selectField('Фенотип из заключения','phenotype',Object.entries(phenotypeNames),p.phenotype)}${inputField('Как подтверждён диагноз','diagnosis',p.diagnosis,'text',true)}${inputField('Возраст, полных лет','age',p.age,'number',true,'min="0" max="120" step="1"')}${selectField('Место / маршрут по решению врача','setting',[['home','Домашний путь назначен врачом'],['specialist','Отдельное ведение со специалистом']],p.setting)}${selectField('Астма / бронхообструкция по заключению','asthma',[['unknown','Нужно уточнить'],['none','Не отмечена'],['controlled','Контролируется; маршрут согласован специалистом'],['uncontrolled','Не контролируется / обострение']],p.asthma)}<label class="em-check"><input name="anaphylaxis" type="checkbox" ${p.anaphylaxis?'checked':''}><span>Анафилаксия в анамнезе на яйцо или продукты с яйцом</span></label><div id="fpies-fields" ${p.phenotype==='fpies'?'':'hidden'}>${selectField('Тяжесть FPIES по заключению','fpiesSeverity',[['unknown','Не уточнена'],['mild','Лёгкий / умеренный: отдельный план специалиста'],['severe','Тяжёлый: вялость, гипотензия, инфузии / госпитализация']],p.fpiesSeverity)}</div>${inputField('Последняя реакция: дата, форма яйца, количество, проявления','lastReaction',p.lastReaction)}<label class="em-check"><input name="clinicianConfirmed" type="checkbox" ${p.clinicianConfirmed?'checked':''}><span>Маршрут и условия перенесены из индивидуального назначения врача</span></label><div id="route-advice" class="em-notice" aria-live="polite">${routeStatus(p)}</div><p class="em-small">Это запись решения врача, а не анкета допуска. Возраст, анафилаксия и контроль астмы требуют оценки специалиста; приложение не делает вывод по уровню IgE. Специализированные маршруты доступны для наблюдений, без общего счётчика перехода.</p></fieldset><fieldset class="clinical-fields" id="standard-recipe-fields"><legend>2. Рецепт и порция</legend>${inputField('Основа / дата назначения','protocol',p.protocol,'text',true)}<label class="form-field">Конкретный рецепт и ступень<select name="recipeId" id="plan-recipeId">${recipes.map(r=>`<option value="${r.id}" ${r.id===p.recipeId?'selected':''} ${r.blocked?'disabled':''}>${r.step}. ${esc(r.name)}${r.blocked?' — требует уточнения':''}</option>`).join('')}</select></label><div id="plan-recipe-info" class="em-notice"></div><p class="em-small">Спорные рецептуры остаются в справочнике, но пока недоступны для назначения в приложении. Это не оценка переносимости остальных рецептов.</p>${inputField('Стартовое количество из назначения','initial',p.initial,'text',true)}${inputField('Целевая порция готового продукта, г / шт. / доля','amount',p.amount,'text',true)}${inputField('Отдельный показатель белка: значение, единица и метод либо «не задан»','protein',p.protein,'text',true)}<p class="em-small">Расчётный нутритивный белок, лабораторный Egg Content и Gal d 1 / Gal d 2 — разные показатели. До сверки первоисточника автопересчёт не используется.</p>${inputField('Цель ступени','goal',p.goal,'text',true)}</fieldset><fieldset class="clinical-fields" id="standard-observation-fields"><legend>3. Частота, сроки и наблюдение</legend><p class="em-note">Все числа ниже задаёт врач. Приложение не подставляет рекомендуемые сроки или дозы.</p>${inputField('Начало текущего назначения','start',p.start,'date',true,'max="'+today()+'"')}${inputField('Частота / наращивание из назначения','frequency',p.frequency,'text',true)}${inputField('Минимальное время на ступени, дней','minDays',p.minDays,'number',true,'min="0" max="3650" step="1"')}${inputField('Полные приёмы на отдельных датах для обсуждения, N','fullRequired',p.fullRequired,'number',true,'min="1" max="1000" step="1"')}${inputField('Непосредственное наблюдение, часов','immediateHours',p.immediateHours,'number',true,'min="0" max="168" step="0.25"')}${inputField('Отсроченное наблюдение от приёма, часов','delayedHours',p.delayedHours,'number',true,'min="0" max="720" step="0.25"')}<p class="em-small">Оба интервала отсчитываются от приёма. Истечение времени без отметки семьи не означает завершённое наблюдение. Ноль допустим только если такое окно не назначено врачом.</p>${inputField('После перерыва: когда связаться с врачом и как возобновлять','restart',p.restart,'text',true)}${inputField('План помощи и связь с врачом','contact',p.contact,'text',true)}${inputField('Решение врача о дальнейшем этапе / дата, если уже есть','nextDecision',p.nextDecision)}<p class="em-small">Запись решения не переключает ступень автоматически. Для следующего этапа вносится новое назначение; прошлые записи сохраняют прежний рецепт и цель.</p></fieldset><fieldset class="clinical-fields" id="specialist-plan-fields"><legend>Отдельный план специалиста</legend><label class="form-field">Назначение: наблюдение, обследования, место введения, связь и помощь<textarea name="specialistPlan" required maxlength="2000" rows="6" placeholder="Перенесите отдельное назначение; общий алгоритм ступеней здесь не применяется">${esc(p.specialistPlan||'')}</textarea></label><p class="em-note">Можно вести дневник уже произошедших событий. Назначение при FPIES или EoE/EGID нельзя заменить счётчиком полных порций. При неясном диагнозе сначала требуется диагностическая оценка.</p></fieldset><label class="em-check"><input type="checkbox" required><span>Переношу готовое назначение врача. Начало и изменения согласованы с врачом.</span></label><button class="em-primary em-wide" type="submit">Сохранить план врача</button></form>`;};
const todayV05=screens.today;
screens.today=()=>{let t=todayV05();if(!state.assigned)return t;const r=clinicalRecipe();const card=state.restricted?`<div class="em-card" id="current-step-card"><span class="em-pill">Отдельное ведение</span><h3>${esc(phenotypeNames[state.plan.phenotype])}</h3><p class="em-note">${routeStatus(state.plan)}</p><p class="em-note">${esc(state.plan.specialistPlan||'Следуйте отдельному назначению специалиста.')}</p><button class="em-primary em-wide" data-action="new-observation">Записать наблюдение</button><button class="em-link" data-go="plan">Открыть план специалиста</button></div>`:`<div class="em-card em-current" id="current-step-card"><span class="em-pill">Ступень ${r.step} из 7${state.paused?' · пауза':state.restricted?' · отдельное ведение':''}</span><h3 style="margin-top:15px">${esc(r.name)}</h3><p class="em-note">${r.id} · ${r.version}</p><div class="em-dose">Цель: ${esc(state.plan.amount)}</div><p class="em-note">${esc(state.plan.goal)}</p><p class="em-small">${esc(state.plan.protein)}</p><p class="em-note">Для обсуждения: ${state.plan.fullRequired} полных приёмов на отдельных датах; не менее ${state.plan.minDays} дней по назначению; оба окна наблюдения завершены, симптомы не отмечены. Решение о завершении ступени принимает врач.</p><p class="em-small">${state.restricted?'Общий счётчик перехода для этого маршрута не применяется.':''}</p><button class="em-primary em-wide" data-action="new-entry">Записать приём или пропуск</button><button class="em-link" data-go="recipe">Продукт и приготовление</button></div>`;t=t.replace(/<div class="em-card em-current" id="current-step-card">[\s\S]*?(?=<div class="em-card" id="daily-card">)/,card+'\n');return t+`<p class="em-small">Основа: Hicks, 2026 · аналитическая стандартизация. Клиническая валидация этой семиступенчатой лестницы не проводилась.</p>`;};
function entryWindowsClosed(r){if(!r.context||r.context.immediateHours===''||r.context.delayedHours===''||r.context.immediateHours==null||r.context.delayedHours==null)return false;const elapsed=(Date.now()-Date.parse(r.occurredAt))/3600000;return Number.isFinite(elapsed)&&elapsed>=Number(r.context.immediateHours)&&elapsed>=Number(r.context.delayedHours)&&r.immediateDone&&r.delayedDone;}
const reportV05=screens.report;screens.report=()=>reportV05()+`<div class="em-card"><h3>Клинический маршрут и наблюдение</h3><p class="em-note">${esc(phenotypeNames[state.plan.phenotype])}. ${routeStatus(state.plan)}</p>${metrics([['Рецепт',state.restricted?'Общая лестница не назначена':clinicalRecipe().name+' · '+clinicalRecipe().version],['Показатель белка',state.plan.protein],['Стартовая порция',state.plan.initial],['После перерыва',state.plan.restart],['Решение о следующем этапе',state.plan.nextDecision||'Не внесено']])}</div>`+(state.restricted?`<div class="em-card"><h3>Отдельное назначение</h3><p class="em-note">${esc(state.plan.specialistPlan)}</p></div>`:'')+evidence();
const aboutV05=screens.about;screens.about=()=>aboutV05()+evidence();
const guideV05=screens.guide;screens.guide=()=>guideV05().replace('<label class="em-check"><input type="checkbox" id="em-read-guide"',evidence()+'<label class="em-check"><input type="checkbox" id="em-read-guide"');
const rulesV05=screens.rules;screens.rules=()=>rulesV05().replace('<summary>Наблюдение и обсуждение следующей ступени</summary>','<summary>Наблюдение и обсуждение следующей ступени</summary><p class="em-note">Непосредственное и отсроченное окна задаются отдельно в плане врача. Для обсуждения учитываются полная порция × назначенное N отдельных дат, минимальное время на ступени и завершение обоих окон без отмеченных симптомов. Эти параметры не являются клинически валидированным универсальным правилом.</p>');
const moreV05=screens.more;
screens.more=()=>moreV05().replace('— исследовательская работа, приведённая в авторском обзоре. Не используется в приложении как готовый утверждённый домашний протокол.','— выбранная рецептурная основа семи ступеней. Аналитическая стандартизация; клиническая валидация этой лестницы не проводилась. Использована русская редакционная адаптация предоставленного сборника.').replace('Конкретный маршрут для «ЕмЯйцо» предстоит согласовать с автором-врачом.','Семиступенчатая основа выбрана для приложения. Индивидуальный клинический маршрут и рецептуру согласует лечащий врач.').replace('Медицинские критерии и конкретный протокол ещё не утверждены, клиническая валидация приложения не проводилась.','Рецептурная основа — Hicks 2026; соответствие оригинальному приложению S2 ещё требует сверки. Клиническая валидация лестницы и приложения не проводилась.').replace('<h3>Исследования стандартизации</h3>','<h3>Выбранная основа: семь ступеней</h3>').replace('</details>\n<details id="sources">','<p class="em-note">При FPIES нужен отдельный маршрут специалиста. При EoE/EGID дневник симптомов не заменяет контроль заболевания и обследование; общий домашний счётчик не применяется.</p></details>\n<details id="sources">')+evidence()+`<details><summary>Дополнительные источники по маршрутам</summary><p class="em-note"><a href="https://doi.org/10.1186/s13223-021-00583-w" target="_blank" rel="noopener noreferrer">Canadian food ladders, 2021</a> — отбор для домашнего ведения, отдельная схема, не замена семи ступеней Hicks.</p><p class="em-note"><a href="https://pubmed.ncbi.nlm.nih.gov/38901613/" target="_blank" rel="noopener noreferrer">Систематический обзор, 2024</a> — ограниченная уверенность в клинических эффектах лестниц; не обещаем ускоренное исчезновение аллергии.</p><p class="em-note"><a href="https://pubmed.ncbi.nlm.nih.gov/37803461/" target="_blank" rel="noopener noreferrer">FPIES: серия случаев, 2023</a> — ограниченные данные, не универсальный домашний допуск.</p><p class="em-note"><a href="https://pubmed.ncbi.nlm.nih.gov/39745304/" target="_blank" rel="noopener noreferrer">ACG: EoE, 2025</a> — отдельные принципы контроля заболевания.</p><p class="em-small">Ссылки и сведения перенесены из предоставленного обзора; полные первоисточники в этой версии независимо не сверены.</p></details>`;

// Recipe choice is an application design rule, not a clinically validated Hicks algorithm.
const METRICS_SOURCE='Таблица автора от 10.10.2026';
const projectRule=()=>notice('<strong>Проектное правило приложения.</strong> Выбор и замена рецепта, отдельный учёт результата и долей порции не являются клинически валидированным алгоритмом Hicks.');
const recipeById=id=>recipes.find(r=>r.id===id);
const mg=(v,approx=false)=>v===null?'—':(approx?'≈ ':'')+Number(v).toLocaleString('ru-RU')+' мг';
function recipeMetrics(r){return {recipeId:r.id,recipeVersion:r.version,recipeName:r.name,stage:r.step,fullPortion:r.portion,fullUnits:r.fullUnits,unitGenitive:r.unitGenitive,estimatedProteinMg:r.estimatedProteinMg,measuredAllergenMg:r.measuredAllergenMg,measuredProteinMg:r.measuredProteinMg,approximate:r.approximate,metricsVersion:r.metricsVersion,source:METRICS_SOURCE};}
function proteinRows(r){return metrics([['Полная порция',r.portion||r.fullPortion],['Расчётный яичный белок',mg(r.estimatedProteinMg,r.approximate)],['Измеренный яичный аллерген',mg(r.measuredAllergenMg)],['Измеренный яичный белок',mg(r.measuredProteinMg)]]);}
function proteinDetails(r,open=false){return `<details ${open?'open':''}><summary>Показатели для врача · на полную порцию</summary>${proteinRows(r)}<p class="em-small">${METRICS_SOURCE}. «—» означает отсутствие данных, а не ноль. Это три разных показателя. Они не характеризуют безопасную дозу для ребёнка и не подтверждают эквивалентность блюд.</p></details>`;}
function doctorTable(items=recipes){return `<div class="table-scroll" tabindex="0" role="region" aria-label="Показатели рецептов для врача"><table class="protein-table"><caption>На полную порцию · все показатели в мг</caption><thead><tr><th scope="col">Ступень</th><th scope="col">Рецепт</th><th scope="col">Полная порция</th><th scope="col">Расчётный яичный белок</th><th scope="col">Измеренный яичный аллерген</th><th scope="col">Измеренный яичный белок</th></tr></thead><tbody>${items.map(r=>`<tr data-metric-recipe="${esc(r.id||r.recipeId)}"><td>${r.step||r.stage}</td><th scope="row">${esc(r.name||r.recipeName)}</th><td>${esc(r.portion||r.fullPortion)}</td><td>${mg(r.estimatedProteinMg,r.approximate)}</td><td>${mg(r.measuredAllergenMg)}</td><td>${mg(r.measuredProteinMg)}</td></tr>`).join('')}</tbody></table></div>`;}
function approvedRecipes(p=state.plan){return (p.allowedRecipes||[]).filter(a=>recipeById(a.recipeId)?.step===Number(p.stage)&&a.start.trim()&&a.schedule.trim());}
function syncSelectedPlan(){const r=recipeById(state.plan.recipeId),a=approvedRecipes().find(x=>x.recipeId===r?.id);state.plan.amount=r?r.portion:'Рецепт ещё не выбран';state.plan.initial=a?.start||'Выберите рецепт с согласованным стартом';state.plan.protein=r?`На полную порцию: расчётный белок ${mg(r.estimatedProteinMg,r.approximate)}; измеренный аллерген ${mg(r.measuredAllergenMg)}; измеренный белок ${mg(r.measuredProteinMg)}.`:'Показатели зависят от выбранного рецепта.';}
planSnapshot=function(){const p=state.plan,r=recipeById(p.recipeId),a=approvedRecipes().find(x=>x.recipeId===r?.id);return {planId:p.id,courseId:state.course?.id||null,stage:r?.step||p.stage,recipeId:r?.id||null,recipeVersion:r?.version||null,recipeName:r?.name||'Рецепт не выбран / отдельное наблюдение',target:r?.portion||'Не задана',protein:p.protein,metrics:r?recipeMetrics(r):null,start:a?.start||'',schedule:a?.schedule||'',immediateHours:p.immediateHours,delayedHours:p.delayedHours};};
function gcd(a,b){while(b){[a,b]=[b,a%b];}return a;}
function fractionLabel(n,d){if(!Number.isInteger(n)||!Number.isInteger(d)||d<=0||n<=0)return '—';const k=gcd(n,d);n/=k;d/=k;const t=n+'/'+d;return d===1?String(n):({'1/4':'¼','1/2':'½','3/4':'¾','1/8':'⅛','3/8':'⅜','5/8':'⅝','7/8':'⅞'}[t]||t);}
function actualFood(f,m){if(!f||!m)return '';let n=f.numerator*m.fullUnits,d=f.denominator;if(m.fullUnits===.5){n=f.numerator;d*=2;}return fractionLabel(n,d)+' '+m.unitGenitive;}
function fullRecipeRecord(r){return r.kind==='intake'&&r.productClass==='standard'&&r.context?.recipeId&&r.recipeMatch&&Number.isInteger(r.fraction?.numerator)&&r.fraction.numerator>0&&r.fraction.numerator===r.fraction.denominator&&r.symptom==='none'&&entryWindowsClosed(r);}
function recipeHistory(id){const rows=state.records.filter(r=>r.context?.recipeId===id&&r.context?.recipeVersion===recipeById(id)?.version);return {full:rows.filter(fullRecipeRecord).length,reactions:rows.filter(r=>['symptom','danger'].includes(r.symptom)).length};}
progressInfo=function(){const p=state.plan,c=state.course;const rows=c?state.records.filter(r=>r.context?.planId===p.id&&r.context?.courseId===c.id&&r.context?.recipeId===p.recipeId&&r.context?.recipeVersion===recipeById(p.recipeId)?.version&&r.date>=c.startDate):[];const complete=rows.filter(fullRecipeRecord),full=new Set(complete.map(r=>r.date)).size;const pending=rows.filter(r=>r.kind==='intake'&&(r.symptom==='pending'||r.symptom==='none'&&!entryWindowsClosed(r))).length;const symptoms=rows.filter(r=>['symptom','danger'].includes(r.symptom)).length;const start=c?[p.start,c.startDate].filter(Boolean).sort().at(-1):null;const elapsed=start?Math.max(0,Math.floor((Date.parse(today()+'T00:00:00Z')-Date.parse(start+'T00:00:00Z'))/86400000)):0;return {full,complete:complete.length,pending,symptoms,elapsed,ready:!!c&&state.assigned&&!state.restricted&&!state.paused&&full>=Number(p.fullRequired)&&elapsed>=Number(p.minDays)&&!pending&&!symptoms,daily:Object.values(state.daily).every(Boolean)};};
recordContext=function(r){const c=r.context;if(!c)return '';return `<p class="em-small">${esc(c.recipeName)} · ${esc(c.recipeVersion||'без рецепта')}<br>Назначение: ${esc(c.planId)} · период рецепта: ${esc(c.courseId||'не задан')}<br>${r.fraction?`Доля полной порции: ${fractionLabel(r.fraction.numerator,r.fraction.denominator)} · ${esc(actualFood(r.fraction,c.metrics))}<br>`:''}${r.batch?'Партия / приготовление: '+esc(r.batch)+'<br>':''}${r.productClass==='category'?'Другой продукт: эквивалентность не установлена.<br>':''}Непосредственное наблюдение: ${r.immediateDone?'завершено по отметке':'не завершено'}; отсроченное: ${r.delayedDone?'завершено по отметке':'не завершено'}.</p>${c.metrics?proteinDetails(c.metrics):''}`;};
recipeButton=function(r){return `<button class="em-wide recipe-button" data-recipe="${recipes.indexOf(r)}"><strong>${esc(r.name)}</strong><small>Полная порция: ${esc(r.portion)}</small><small>Расчётный яичный белок: ${mg(r.estimatedProteinMg,r.approximate)}</small><small>${state.plan.recipeId===r.id?'Сейчас выбран':approvedRecipes().some(a=>a.recipeId===r.id)?'Разрешён в плане врача':'Справочная карточка · не назначение'}</small></button>`;};
screens.doctorTable=()=>back('more','Памятка')+header('СВЕДЕНИЯ ДЛЯ ВРАЧА','Белок и аллерген','Три отдельных показателя на полную порцию каждого рецепта.')+doctorTable()+`<p class="em-note">${METRICS_SOURCE}. «—» — данных нет. Расчётные значения для цельного яйца приблизительные. Данные лабораторного исследования не являются анализом приготовленной дома партии.</p>`+evidence()+projectRule();
screens.recipe=()=>{const r=recipes[recipeIndex]||recipes[0];return back('recipes','Рецепты и продукты')+header('СТУПЕНЬ '+r.step+' · '+r.id+' · '+r.version,r.name,'Полная порция и три показателя сохранены по таблице автора.')+`<div class="em-card">${proteinRows(r)}<p class="em-small">Все цифры относятся к полной порции. При записи доли блюда приложение не рассчитывает по ней «безопасную дозу» аллергена.</p></div>${r.issue?notice('<strong>Замечание к технологии.</strong> '+esc(r.issue)+' В назначении должна быть согласована конкретная версия рецепта.','warn'):''}<details open><summary>Ингредиенты и приготовление</summary><div class="recipe-body">${r.html}</div></details><p class="em-small">${esc(r.sourceNote)} Возможные замены ингредиентов из кулинарного текста не признаны автоматически эквивалентными.</p><button class="em-wide" data-go="chooseRecipe">Выбор рецепта на текущей ступени</button><button class="em-link" data-go="doctorTable">Полная таблица для врача</button>`+evidence()+projectRule();};
screens.recipes=()=>back('more','Памятка')+header('РЕЦЕПТЫ И ПРОДУКТЫ','Один рецепт.<br>Своя история.','Переносимость полной порции одного блюда не переносится на другое.')+`<button class="em-primary em-wide" data-go="chooseRecipe">Выбрать из разрешённых врачом</button><button class="em-wide" data-go="doctorTable">Таблица белка и аллергена для врача</button>${steps.map((s,i)=>`<details ${i+1===state.plan.stage?'open':''}><summary>${i+1}. ${s}</summary><div class="recipe-list">${recipes.filter(r=>r.step===i+1).map(recipeButton).join('')}</div></details>`).join('')}`+projectRule();
screens.chooseRecipe=()=>{const allowed=approvedRecipes();return back('today','Сегодня')+header('СТУПЕНЬ '+state.plan.stage,'Выбор рецепта','Только из вариантов, разрешённых врачом на этой ступени.')+projectRule()+`${state.paused?notice('После реакции замена рецепта и дальнейшее повышение заблокированы до клинической оценки.','danger')+'<button class="em-wide" data-go="clinicalReview">Решение врача после реакции</button>':''}${!state.assigned||state.restricted||!allowed.length?notice('Сначала нужен индивидуальный план врача с разрешёнными рецептами и стартовым количеством.')+'<button class="em-wide" data-go="plan">Открыть план врача</button>':allowed.map(a=>{const r=recipeById(a.recipeId),h=recipeHistory(r.id),selected=r.id===state.plan.recipeId;return `<div class="em-card recipe-choice"><span class="em-pill">${selected?'Выбран сейчас':'Разрешён врачом в плане врача'}</span><h3 style="margin-top:12px">${esc(r.name)}</h3>${proteinRows(r)}<p class="em-note"><strong>Старт по назначению:</strong> ${esc(a.start)}</p><p class="em-note"><strong>Схема увеличения:</strong> ${esc(a.schedule)}</p><p class="em-small">В истории этого рецепта: полных приёмов с завершённым наблюдением без отмеченных симптомов — ${h.full}; записей с реакцией — ${h.reactions}. Это сведения дневника, не клиническое заключение.</p><button class="em-wide" data-choose-recipe="${r.id}" ${state.paused||selected?'disabled':''}>${selected?'Этот рецепт выбран':state.plan.recipeId?'Заменить на этот рецепт':'Выбрать этот рецепт'}</button><button class="em-link" data-recipe="${recipes.indexOf(r)}">Ингредиенты и приготовление</button></div>`;}).join('')}`;};
let pendingRecipe=null;
screens.recipeChange=()=>{const r=recipeById(pendingRecipe),a=approvedRecipes().find(x=>x.recipeId===pendingRecipe);if(!r||!a)return screens.chooseRecipe();const old=recipeById(state.plan.recipeId);return back('chooseRecipe','К разрешённым рецептам')+header(old?'ЗАМЕНА НА ТОЙ ЖЕ СТУПЕНИ':'ВЫБОР ПРИ ВХОДЕ НА СТУПЕНЬ',r.name)+`<div class="change-warning"><strong>У нового блюда — своя порция и матрица.</strong><p>${old?esc(old.name)+': '+esc(old.portion)+', '+mg(old.estimatedProteinMg,old.approximate)+' расчётного яичного белка. ':''}${esc(r.name)}: ${esc(r.portion)}, ${mg(r.estimatedProteinMg,r.approximate)} расчётного яичного белка.</p><p>Отметка о полной переносимой порции предыдущего блюда не переносится. Новый рецепт начинается с согласованного количества; подсчёт повторных приёмов начинается отдельно.</p></div>${proteinDetails(r,true)}<div class="em-card"><h3>Назначение для этого рецепта</h3><p>${esc(a.start)}</p><p>${esc(a.schedule)}</p></div><form id="recipe-choice-form"><label class="em-check"><input name="confirmStart" type="checkbox" required><span>Стартовое количество и схема именно для этого рецепта согласованы с врачом. Понимаю, что результат другого блюда не переносится.</span></label><button type="submit" class="em-primary em-wide" ${state.paused?'disabled':''}>Подтвердить выбор рецепта</button></form>`+projectRule();};
function selectApprovedRecipe(id){const r=recipeById(id),a=approvedRecipes().find(x=>x.recipeId===id);if(state.paused||state.restricted||!state.assigned||!a||r.step!==state.plan.stage)return false;if(id===state.plan.recipeId)return false;state.plan.recipeId=id;state.course={id:crypto.randomUUID(),planId:state.plan.id,recipeId:id,startDate:today()};state.daily={well:false,asthma:false,changes:false,prepared:false};syncSelectedPlan();recipeIndex=recipes.indexOf(r);return true;}
const todayV06=screens.today;
screens.today=()=>{let t=todayV06();if(!state.assigned||state.restricted)return t;const r=recipeById(state.plan.recipeId),a=approvedRecipes().find(x=>x.recipeId===r?.id),q=progressInfo();const card=`<div class="em-card em-current" id="current-step-card"><span class="em-pill">Ступень ${state.plan.stage} из 7${state.paused?' · пауза':''}</span><h3 style="margin-top:15px">${r?esc(r.name):'Выберите рецепт'}</h3>${r?`<p class="em-note"><strong>Цель ступени:</strong> ${esc(state.plan.goal)}</p><div class="em-dose">Полная порция:<br>${esc(r.portion)}</div><p class="em-note"><strong>Старт:</strong> ${esc(a?.start)}</p><p class="em-note"><strong>Схема из назначения:</strong> ${esc(a?.schedule)}</p><p class="em-note">${q.full?'Полная порция этого рецепта отмечена без симптомов по завершённым наблюдениям.':'Полная порция этого рецепта пока не отмечена с завершённым наблюдением.'} Для обсуждения: ${q.full} / ${state.plan.fullRequired} отдельных дат, срок и наблюдение по плану врача.</p><button class="em-primary em-wide" data-action="new-entry">Записать приём или пропуск</button><button class="em-link" data-go="recipe">Продукт и приготовление</button><br><button class="em-link" data-go="chooseRecipe">Выбор или замена рецепта</button>${proteinDetails(r)}`:'<p class="em-note">Врач разрешил варианты на этой ступени. Полная порция и стартовая схема появятся после выбора.</p><button class="em-primary em-wide" data-go="chooseRecipe">Выбрать рецепт</button>'}${state.paused?'<button class="em-wide" data-go="clinicalReview">Решение врача после реакции</button>':''}</div>`;return t.replace(/<div class="em-card em-current" id="current-step-card">[\s\S]*?(?=<div class="em-card" id="daily-card">)/,card);};
const planV06=screens.plan;
function approvalFields(stage,draft){return recipes.filter(r=>r.step===Number(stage)).map(r=>{const a=draft.find(x=>x.recipeId===r.id);return `<div class="recipe-approval" data-approval="${r.id}"><label class="em-check"><input type="checkbox" name="allowed" value="${r.id}" ${a?'checked':''}><span><strong>${esc(r.name)}</strong><br>Разрешён врачом на этой ступени</span></label><p class="em-small">Полная порция: ${esc(r.portion)}. ${r.issue?esc(r.issue):''}</p><fieldset data-approval-fields ${a?'':'disabled'} style="border:0;padding:0;margin:0">${inputField('Стартовое количество именно этого блюда, с единицей','start-'+r.id,a?.start||'','text',true)}<label class="form-field">Индивидуальная схема увеличения и повторения<textarea name="schedule-${r.id}" rows="3" maxlength="2000" required>${esc(a?.schedule||'')}</textarea></label></fieldset><button type="button" class="em-link" data-recipe="${recipes.indexOf(r)}">Карточка и показатели для врача</button></div>`;}).join('');}
screens.plan=()=>{const p=state.plan;const replacement=`<fieldset class="clinical-fields" id="standard-recipe-fields"><legend>2. Ступень и разрешённые рецепты</legend>${inputField('Основа / дата назначения','protocol',p.protocol,'text',true)}${selectField('Ступень из назначения','stage',steps.map((s,i)=>[String(i+1),(i+1)+'. '+s]),String(p.stage))}<p class="em-note">Разрешите один или несколько рецептов. Для каждого отдельно укажите старт и схему. Пациент выбирает среди них; наличие рецепта в каталоге не является назначением.</p><div id="approved-recipe-fields">${approvalFields(p.stage,p.allowedRecipes||[])}</div><p class="input-error" id="plan-error" role="alert"></p>${inputField('Цель ступени','goal',p.goal,'text',true)}<button type="button" class="em-wide" data-go="doctorTable">Таблица показателей для врача</button>${projectRule()}</fieldset>`;return planV06().replace(/<fieldset class="clinical-fields" id="standard-recipe-fields">[\s\S]*?<\/fieldset>/,replacement).replace('Для следующего этапа вносится новое назначение; прошлые записи сохраняют прежний рецепт и цель.','Для следующего этапа вносится новое назначение; затем пациент выбирает разрешённый рецепт. Прежние записи сохраняют рецепт, порцию и показатели.');};
screens.progress=()=>{const p=state.plan,q=progressInfo(),r=recipeById(p.recipeId);if(state.restricted)return back('today','Сегодня')+header('ОТДЕЛЬНОЕ ВЕДЕНИЕ','Дальнейший план — со специалистом')+notice(routeStatus(p))+`<p>${esc(p.specialistPlan)}</p><button class="em-wide" data-go="report">Отчёт для врача</button>`;return back('today','Сегодня')+header('ПОВТОРНАЯ ПЕРЕНОСИМОСТЬ ПО ДНЕВНИКУ','Обсуждаем следующую ступень')+notice(state.paused?'После реакции повышение количества и переход заблокированы до клинической оценки.':!r?'Сначала выберите рецепт из разрешённых врачом.':q.ready?'По записям выполнены назначенные условия для обсуждения. Переход возможен только по решению врача.':'Не все условия повторной переносимости отражены как выполненные.',state.paused?'danger':'')+`<div class="em-card"><h3>${r?esc(r.name):'Рецепт не выбран'}</h3>${metrics([['Полная порция',r?.portion||'—'],['Полные приёмы на отдельных датах',q.full+' / '+p.fullRequired],['Время в текущем периоде рецепта',q.elapsed+' / '+p.minDays+' дней'],['Незавершённые наблюдения',q.pending],['Записи с симптомами',q.symptoms]])}<p class="em-note">Один успешный приём не завершает ступень. Число повторений и сроки задаёт врач.</p><p class="em-small">Смена блюда начинает отдельный период. Неполные порции не складываются в полную; повторные записи одной даты дают одну дату. Оба окна наблюдения должны быть завершены по времени и отметке семьи.</p></div><div class="em-card"><h3>Решение врача</h3><p>${esc(p.nextDecision||'Не внесено')}</p></div><button class="em-wide" data-action="add-transition-question" ${state.question?'disabled':''}>${state.question?'Вопрос добавлен в отчёт':'Добавить вопрос о переходе в отчёт'}</button><button class="em-link" data-go="report">Отчёт для врача</button>${state.paused?'<button class="em-wide" data-go="clinicalReview">Решение врача после реакции</button>':''}`+projectRule();};
screens.entry=()=>{const r=state.records.find(x=>x.id===editId),c=r?.context||planSnapshot(),m=c.metrics;return back('diary','К дневнику')+header('ЗАПИСЬ В ДНЕВНИК',r?'Уточнить запись':'Что произошло?','Доля относится к полной порции блюда, а не к безопасной дозе аллергена.')+notice(esc(c.recipeName)+(r?'. При уточнении сохраняются прежние рецепт, назначение и показатели.':'. Записывайте фактически произошедшее.'))+`<form id="entry-form">${selectField('Тип записи','kind',[['intake','Приём продукта'],['skip','Приёма не было'],['observation','Наблюдение без приёма']],r?.kind||'intake').replace('id="plan-kind"','id="kind"')}<div class="grid2">${inputField('Дата','date',r?.date||today(),'date',true,'max="'+today()+'" min="1900-01-01"')}${inputField('Время','time',r?.time||new Date().toTimeString().slice(0,5),'time',true)}</div><div id="intake-fields">${selectField('Какой продукт фактически был','productClass',m?[['standard','Выбранный рецепт из назначения'],['category','Другой / магазинный продукт']]:[['category','Другой продукт / рецепт не выбран']],r?.productClass||(m?'standard':'category'))}<div id="fraction-fields"><p class="em-note">Полная порция: <strong>${esc(m?.fullPortion||'Не задана')}</strong>.</p><p class="em-small">Отметьте съеденную долю. Это кнопки записи, не рекомендации увеличивать количество.</p><div class="fraction-buttons">${[['1','8'],['1','4'],['1','2'],['3','4'],['1','1']].map(([n,d])=>`<button type="button" data-fraction="${n}/${d}">${fractionLabel(+n,+d)}</button>`).join('')}</div><div class="grid2">${inputField('Числитель доли','numerator',r?.fraction?.numerator||'','number',true,'min="1" max="1000" step="1"')}${inputField('Знаменатель доли','denominator',r?.fraction?.denominator||1,'number',true,'min="1" max="1000" step="1"')}</div><p id="fraction-description" class="em-notice" aria-live="polite"></p></div><label class="form-field" id="other-amount">Фактически съеденный продукт и количество<textarea name="otherAmount" maxlength="500">${esc(r?.productClass==='category'?r.amount:'')}</textarea></label>${inputField('Партия / дата, выход и приготовление','batch',r?.batch||'')}<label class="em-check" id="recipe-match-label"><input type="checkbox" name="recipeMatch" ${r?.recipeMatch?'checked':''}><span>Состав, выход партии и приготовление соответствуют выбранной версии рецепта</span></label></div><div id="symptom-fields"><p class="em-note">По сохранённому назначению: непосредственное наблюдение ${esc(c.immediateHours)} ч; отсроченное ${esc(c.delayedHours)} ч от приёма.</p><label class="em-check"><input type="checkbox" name="immediateDone" ${r?.immediateDone?'checked':''}><span>Непосредственное наблюдение завершено</span></label><label class="em-check"><input type="checkbox" name="delayedDone" ${r?.delayedDone?'checked':''}><span>Отсроченное наблюдение завершено</span></label>${selectField('Результат наблюдения','symptom',[['pending','Наблюдение продолжается'],['none','Наблюдение завершено, симптомов не отмечено'],['symptom','Появились симптомы'],['danger','Есть опасные признаки']],r?.symptom==='skip'?'pending':r?.symptom||'pending')}<div id="symptom-extra">${inputField('Когда появились симптомы','onset',r?.onset||'')}</div><div id="reaction-note" class="em-notice em-alert">Прекратите текущую пробу, выполняйте индивидуальный план помощи и свяжитесь с врачом. Повышение количества и переход блокируются до клинической оценки.</div><div id="urgent" class="em-notice em-alert"><strong>Сначала помощь, затем запись.</strong><p>При подозрении на анафилаксию немедленно используйте назначенный адреналин по индивидуальному плану и вызывайте 112 / 103. Не ждите сохранения записи или ответа врача в чате.</p><button type="button" class="em-wide" data-go="help">План срочной помощи</button></div></div><label class="form-field">Комментарий<textarea name="note" maxlength="1000" rows="3">${esc(r?.note||'')}</textarea></label><p class="input-error" id="entry-error" role="alert"></p><button class="em-primary em-wide" type="submit">${r?'Сохранить уточнение':'Добавить в дневник'}</button></form>${m?proteinDetails(m):''}`;};
function bindEntryV07(){const form=$('#entry-form'),previous=state.records.find(x=>x.id===editId),c=previous?.context||planSnapshot();const update=()=>{const f=form.elements, intake=f.kind.value==='intake',standard=intake&&f.productClass.value==='standard'&&!!c.metrics;$('#intake-fields').hidden=!intake;$('#fraction-fields').hidden=!standard;$('#other-amount').hidden=!intake||standard;$('#recipe-match-label').hidden=!standard;f.numerator.required=f.denominator.required=standard;f.numerator.disabled=f.denominator.disabled=!standard;f.otherAmount.required=intake&&!standard;f.otherAmount.disabled=!intake||standard;$('#symptom-fields').hidden=f.kind.value==='skip';const symptom=f.symptom.value;f.onset.required=f.kind.value!=='skip'&&['symptom','danger'].includes(symptom);$('#symptom-extra').hidden=!['symptom','danger'].includes(symptom);$('#reaction-note').hidden=symptom!=='symptom';$('#urgent').hidden=symptom!=='danger';f.note.required=!intake;const fraction={numerator:Number(f.numerator.value),denominator:Number(f.denominator.value)};$('#fraction-description').textContent=fraction.numerator>0&&fraction.denominator>0?`${fractionLabel(fraction.numerator,fraction.denominator)} полной порции = ${actualFood(fraction,c.metrics)}. ${fraction.numerator===fraction.denominator?'Это полная порция выбранного блюда.':'Это отдельная запись; малые порции не суммируются.'}`:'Укажите фактически съеденную долю.';};form.addEventListener('change',update);form.addEventListener('input',update);form.querySelectorAll('[data-fraction]').forEach(b=>b.addEventListener('click',()=>{const [n,d]=b.dataset.fraction.split('/');form.elements.numerator.value=n;form.elements.denominator.value=d;update();}));update();form.addEventListener('submit',e=>{e.preventDefault();const f=new FormData(form),kind=f.get('kind'),standard=kind==='intake'&&f.get('productClass')==='standard'&&!!c.metrics;let fraction=standard?{numerator:Number(f.get('numerator')),denominator:Number(f.get('denominator'))}:null;if(fraction&&(!Number.isInteger(fraction.numerator)||!Number.isInteger(fraction.denominator)||fraction.numerator<=0||fraction.denominator<=0||fraction.numerator>1000||fraction.denominator>1000)){$('#entry-error').textContent='Укажите корректную положительную долю.';return;}const symptom=kind==='skip'?'skip':f.get('symptom');if(!/^\d{4}-\d{2}-\d{2}$/.test(String(f.get('date')))||!/^([01]\d|2[0-3]):[0-5]\d$/.test(String(f.get('time'))))return;const occurredAt=previous&&previous.date===f.get('date')&&previous.time===f.get('time')?previous.occurredAt:new Date(f.get('date')+'T'+f.get('time')).toISOString();if(Date.parse(occurredAt)>Date.now()){$('#entry-error').textContent='Запись не может относиться к будущему времени.';return;}const r={occurredAt,updatedAt:new Date().toISOString(),id:previous?.id||crypto.randomUUID(),context:structuredClone(c),date:f.get('date'),time:f.get('time'),kind,productClass:standard?'standard':'category',fraction,amount:kind!=='intake'?'':standard?actualFood(fraction,c.metrics)+' · '+fractionLabel(fraction.numerator,fraction.denominator)+' полной порции':String(f.get('otherAmount')||'').trim(),unit:'',phase:'Наблюдение за рецептом',targetMet:standard&&fraction.numerator===fraction.denominator,recipeMatch:standard&&f.has('recipeMatch'),batch:String(f.get('batch')||''),immediateDone:f.has('immediateDone'),delayedDone:f.has('delayedDone'),symptom,onset:['symptom','danger'].includes(symptom)?String(f.get('onset')||''):'',note:String(f.get('note')||'').trim()};if(['symptom','danger'].includes(r.symptom)&&!r.onset.trim()){$('#entry-error').textContent='Укажите, когда появились симптомы.';return;}if(kind==='intake'&&!r.amount){$('#entry-error').textContent='Укажите продукт и количество.';return;}if(r.symptom==='none'&&kind==='intake'&&!entryWindowsClosed(r))r.symptom='pending';if(['symptom','danger'].includes(r.symptom)){state.paused=true;state.reactionAt=new Date().toISOString();state.pauseReason='Отмечены симптомы в записи '+r.date+' '+r.time;}if(previous)state.records[state.records.indexOf(previous)]=r;else state.records.push(r);editId=null;filter='all';dateFilter='';render('diary');message('Запись сохранена. Исходные показатели относятся к полной порции, не к безопасной дозе.');});}
function planSignature(p){return JSON.stringify(['protocol','phenotype','setting','diagnosis','age','anaphylaxis','asthma','fpiesSeverity','lastReaction','clinicianConfirmed','stage','start','minDays','fullRequired','immediateHours','delayedHours','frequency','goal','restart','contact','nextDecision','specialistPlan'].map(k=>[k,String(p[k]??'')]).concat([['allowedRecipes',(p.allowedRecipes||[]).slice().sort((a,b)=>a.recipeId.localeCompare(b.recipeId))]]));}
function bindPlanV07(){const form=$('#plan-form');let draft=structuredClone(state.plan.allowedRecipes||[]);function capture(){const ids=[...form.querySelectorAll('[data-approval]')].map(x=>x.dataset.approval);draft=draft.filter(a=>!ids.includes(a.recipeId));for(const id of ids){if(form.querySelector(`[name="allowed"][value="${id}"]`).checked)draft.push({recipeId:id,start:form.elements['start-'+id].value.trim(),schedule:form.elements['schedule-'+id].value.trim()});}}function read(){const f=new FormData(form),p={...state.plan};for(const k of ['protocol','phenotype','setting','diagnosis','asthma','fpiesSeverity','lastReaction','start','frequency','goal','restart','contact','nextDecision','specialistPlan'])if(f.has(k))p[k]=String(f.get(k)).trim();for(const k of ['stage','age','minDays','fullRequired','immediateHours','delayedHours'])if(f.has(k))p[k]=Number(f.get(k));for(const k of ['anaphylaxis','clinicianConfirmed'])p[k]=f.has(k);return p;}
 function advice(){const p=read(),home=homeRoute(p);$('#route-advice').textContent=routeStatus(p);$('#fpies-fields').hidden=p.phenotype!=='fpies';for(const id of ['standard-recipe-fields','standard-observation-fields']){$('#'+id).hidden=!home;$('#'+id).disabled=!home;}$('#specialist-plan-fields').hidden=home;$('#specialist-plan-fields').disabled=home;}
 form.addEventListener('change',e=>{if(e.target.name==='stage'){capture();$('#approved-recipe-fields').innerHTML=approvalFields(e.target.value,draft);}if(e.target.name==='allowed')e.target.closest('[data-approval]').querySelector('[data-approval-fields]').disabled=!e.target.checked;advice();});advice();form.addEventListener('submit',e=>{e.preventDefault();capture();const p=read();p.allowedRecipes=draft.filter(a=>recipeById(a.recipeId)?.step===p.stage);if(homeRoute(p)&&!p.allowedRecipes.length){$('#plan-error').textContent='Разрешите хотя бы один рецепт и внесите его старт и схему.';return;}if(state.paused&&p.stage!==state.plan.stage){$('#plan-error').textContent='После реакции переход заблокирован. Сначала внесите результат клинической оценки.';return;}if(homeRoute(p)&&p.allowedRecipes.some(a=>!a.start||!a.schedule)){$('#plan-error').textContent='Для каждого разрешённого блюда нужны старт и схема врача.';return;}const changed=planSignature(p)!==planSignature(state.plan);if(changed&&state.assigned)state.planHistory.push(structuredClone(state.plan));p.id=changed?crypto.randomUUID():state.plan.id;if(changed){p.recipeId=null;state.course=null;state.question=false;}p.period=`Не менее ${p.minDays} дней; повторные полные порции на ${p.fullRequired} отдельных датах`;p.observe=`Непосредственное ${p.immediateHours} ч; отсроченное ${p.delayedHours} ч`;p.route=phenotypeNames[p.phenotype];state.plan=p;state.assigned=true;state.restricted=!homeRoute(p);state.daily={well:false,asthma:false,changes:false,prepared:false};syncSelectedPlan();render(state.restricted?'today':changed?'chooseRecipe':'today');message('План врача сохранён. История прежнего назначения сохранена отдельно.');});}
screens.clinicalReview=()=>back('today','Сегодня')+header('ПОСЛЕ РЕАКЦИИ','Решение врача','Перенесите результат уже проведённой клинической оценки. Само заполнение формы не заменяет консультацию.')+`${!state.paused?notice('Пауза сейчас не установлена. Предыдущие решения доступны в отчёте.'):notice('До решения врача повышение количества, замена рецепта и переход остаются заблокированы.','danger')}<form id="clinical-review-form">${inputField('Дата оценки','reviewDate',today(),'date',true,'max="'+today()+'"')}${inputField('Врач / ссылка на заключение','reviewClinician','','text',true)}<label class="form-field">Заключение и дальнейшие действия<textarea name="reviewNote" required maxlength="2000" rows="4"></textarea></label>${selectField('Решение из заключения','reviewDecision',[['pause','Сохранить паузу'],['resume','Возобновление по новому назначению согласовано']],'pause')}<fieldset id="restart-fields" hidden disabled style="border:0;padding:0">${selectField('Рецепт после оценки врача','restartRecipe',approvedRecipes().map(a=>[a.recipeId,recipeById(a.recipeId).name]),state.plan.recipeId||approvedRecipes()[0]?.recipeId)}${inputField('Новый старт: продукт и количество','restartStart','','text',true)}<label class="form-field">Новая схема увеличения и повторения<textarea name="restartSchedule" required maxlength="2000" rows="3"></textarea></label></fieldset><label class="em-check"><input type="checkbox" name="reviewConfirmed" required><span>Клиническая оценка проведена; переношу готовое решение врача и условия дальнейшего ведения.</span></label><p class="input-error" id="review-error" role="alert"></p><button class="em-primary em-wide" type="submit" ${state.paused?'':'disabled'}>Сохранить решение в дневнике</button></form><button class="em-link" data-go="help">План срочной помощи</button>`;
function bindClinicalReview(){const form=$('#clinical-review-form');form.elements.reviewDecision.addEventListener('change',()=>{const resume=form.elements.reviewDecision.value==='resume';$('#restart-fields').hidden=!resume;$('#restart-fields').disabled=!resume;});form.addEventListener('submit',e=>{e.preventDefault();if(!state.paused)return;const f=new FormData(form),resume=f.get('reviewDecision')==='resume',r=recipeById(f.get('restartRecipe'));if(resume&&(!homeRoute(state.plan)||!r||!approvedRecipes().some(a=>a.recipeId===r.id))){$('#review-error').textContent='Для этого маршрута требуется отдельный план специалиста. Общий домашний путь не возобновляется.';return;}if(f.get('reviewDate')<(state.reactionAt||today()).slice(0,10)){$('#review-error').textContent='Дата оценки не может предшествовать зафиксированной реакции.';return;}const review={recordedAt:new Date().toISOString(),id:crypto.randomUUID(),date:f.get('reviewDate'),clinician:String(f.get('reviewClinician')).trim(),note:String(f.get('reviewNote')).trim(),decision:resume?'resume':'pause',previousPlanId:state.plan.id,recipeId:resume?r.id:null,start:resume?String(f.get('restartStart')).trim():null,schedule:resume?String(f.get('restartSchedule')).trim():null};if(!review.clinician||!review.note||resume&&(!review.start||!review.schedule)){$('#review-error').textContent='Перенесите заключение и все условия возобновления.';return;}state.clinicalReviews.push(review);if(resume){state.planHistory.push(structuredClone(state.plan));state.plan={...state.plan,id:crypto.randomUUID(),recipeId:null,start:today(),nextDecision:'',allowedRecipes:[{recipeId:r.id,start:review.start,schedule:review.schedule}]};state.course=null;state.paused=false;state.daily={well:false,asthma:false,changes:false,prepared:false};syncSelectedPlan();}render(resume?'chooseRecipe':'today');message(resume?'Решение врача внесено. Выберите согласованный рецепт; прежние результаты не перенесены.':'Пауза сохранена. Решение добавлено в отчёт.');});}
const reportV06=screens.report;
screens.report=()=>{const used=new Map();state.records.forEach(r=>{if(r.context?.metrics)used.set(r.context.recipeId+'|'+r.context.recipeVersion+'|'+r.context.metrics.metricsVersion,r.context.metrics);});return reportV06()+`<div class="em-card"><h3>Результат по каждому рецепту</h3>${recipes.filter(r=>recipeHistory(r.id).full||recipeHistory(r.id).reactions||r.id===state.plan.recipeId).map(r=>{const h=recipeHistory(r.id);return `<p class="em-note"><strong>${esc(r.name)}</strong>: ${h.full} полных приёмов с завершённым наблюдением без отмеченных симптомов; ${h.reactions} записей с реакцией. ${r.id===state.plan.recipeId?'Текущий рецепт.':'История, не результат другого блюда.'}</p>`;}).join('')}<p class="em-small">Это описание дневника семьи, не заключение о клинической переносимости. Доля блюда записана отдельно; показатели ниже относятся к полной порции.</p></div>${used.size?doctorTable([...used.values()]):''}<div class="em-card"><h3>Клиническая оценка после реакции</h3>${state.clinicalReviews.length?state.clinicalReviews.map(r=>`<p class="em-note">${esc(r.date)} · ${esc(r.clinician)} · ${r.decision==='resume'?'возобновление по новому назначению':'сохранить паузу'}<br>${esc(r.note)}${r.start?'<br>Старт: '+esc(r.start)+'<br>Схема: '+esc(r.schedule):''}</p>`).join(''):'<p class="em-note">Не вносилась.</p>'}</div><button class="em-link" data-go="doctorTable">Полная таблица для врача</button>`;};
reportText=function(){return ['ЕмЯйцо · ОТЧЁТ ДЛЯ ВРАЧА, НЕ НАЗНАЧЕНИЕ','Пациент: '+state.name+' · дата рождения: '+(state.dob||'не указана'),'Клиническая валидация семиступенчатой лестницы Hicks не проводилась.','Выбор и замена рецепта — проектное правило приложения, не валидированный алгоритм Hicks.','Источник показателей: '+METRICS_SOURCE,'Все три показателя ниже относятся к ПОЛНОЙ порции, не к съеденной доле и не к безопасной дозе.','Пауза: '+(state.paused?'да':'нет'),'ПЛАН',JSON.stringify(state.plan,null,2),'ЗАПИСИ',...state.records.map(r=>`${r.date} ${r.time} | ${r.context?.recipeName} | ${r.amount||r.kind} | ${statusLabel(r)}\n`+JSON.stringify({fraction:r.fraction,context:r.context,batch:r.batch,productClass:r.productClass,recipeMatch:r.recipeMatch,immediateDone:r.immediateDone,delayedDone:r.delayedDone,onset:r.onset,note:r.note})), 'КЛИНИЧЕСКАЯ ОЦЕНКА',JSON.stringify(state.clinicalReviews,null,2),'Вопросы: '+state.reportQuestion+(state.question?' Можно ли обсуждать следующую ступень?':'')].join('\n');};
const moreV06=screens.more;screens.more=()=>moreV06()+`<button class="em-wide" data-go="doctorTable">Белок и аллерген · таблица для врача</button><button class="em-wide" data-go="chooseRecipe">Выбор и замена рецепта</button>`+projectRule();
const rulesV06=screens.rules;screens.rules=()=>rulesV06().replace('Наращивание, другой рецепт, незавершённое наблюдение','Неполные порции, другой рецепт, незавершённое наблюдение')+`<details open><summary>Замена рецепта на той же ступени</summary><p class="em-note">Выберите один из разрешённых врачом вариантов. Полная порция, состав и аллергенная матрица у блюд различаются. Результат одного рецепта не переносится на другое блюдо. Начало и увеличение — по отдельной схеме врача для выбранного рецепта.</p><p class="em-note">Пример: 1 банановое печенье — расчётно 250 мг яичного белка. Переносимость этой порции не означает переносимость 2 яблочных печений — расчётно 500 мг.</p><button class="em-link" data-go="chooseRecipe">Разрешённые рецепты</button></details>`+projectRule();
bindScreen=function(){bindScreenBase();if(view==='entry')bindEntryV07();if(view==='plan')bindPlanV07();if(view==='clinicalReview')bindClinicalReview();if(view==='recipeChange')$('#recipe-choice-form')?.addEventListener('submit',e=>{e.preventDefault();if(!e.target.checkValidity())return;if(selectApprovedRecipe(pendingRecipe)){pendingRecipe=null;render('today');message('Рецепт выбран. Полная порция и история другого блюда не перенесены.');}else message('Сейчас смена рецепта недоступна. Проверьте назначение и паузу.');});};
document.addEventListener('click',e=>{const b=e.target.closest('[data-choose-recipe]');if(!b||b.disabled)return;if(state.paused||state.restricted)return;pendingRecipe=b.dataset.chooseRecipe;render('recipeChange');});

const aboutOverlay=FamilyAbout.create({root:document.querySelector('#em-demo'),trigger:'[data-go="about"]',build(){const body=document.createElement('div');body.innerHTML=screens.about();body.querySelector('.back')?.remove();body.querySelector('.eyebrow, .em-eyebrow')?.remove();const title=body.querySelector('h1');if(title){const name=document.createElement('h3');name.textContent=title.textContent;title.replaceWith(name);}body.append(document.querySelector('#author-template').content.cloneNode(true));return body;},activate:()=>applyOriginalIcon(),navigate(next){if(formDirty&&!confirm('Изменения формы ещё не сохранены. Перейти без сохранения?'))return;render(next);}});
